	router.POST(options.BaseURL+"/v2/alert_events/http/:alert_source_config_id", wrapper.AlertEventsV2CreateHTTP)
	router.GET(options.BaseURL+"/v2/incident_updates", wrapper.IncidentUpdatesV2List)
	router.POST(options.BaseURL+"/v2/incident_updates", wrapper.IncidentUpdatesV2Create)
