	router.POST(options.BaseURL+"/v2/incident_timeline_items", wrapper.IncidentTimelineItemsV2Create)
	router.PATCH(options.BaseURL+"/v2/incident_timeline_items/:id", wrapper.IncidentTimelineItemsV2Update)
	router.GET(options.BaseURL+"/v3/actions", wrapper.ActionsV3List)
	router.POST(options.BaseURL+"/v3/actions", wrapper.ActionsV3Create)
	router.DELETE(options.BaseURL+"/v3/actions/:id", wrapper.ActionsV3Delete)
	router.GET(options.BaseURL+"/v3/actions/:id", wrapper.ActionsV3Show)
